from .reader import *  # noqa: F403
from .writer import XmlWriter, JsonWriter
from ta5g_file_system import ta5g_file_system

XML_EXTENSION_TYPE = 'xml'
JSON_EXTENSION_TYPE = 'json'


class ReaderWriterFactoryError(Exception):
    pass


class ReaderWriterFactory(object):
    def __get_file_type(self, file_path):
        file_extension = ta5g_file_system.get_file_extension_from_filepath(file_path)
        return file_extension

    def create_reader(self, file_path):
        reader_type = self.__get_file_type(file_path)
        if reader_type == XML_EXTENSION_TYPE:
            return XmlReader().read(file_path)  # noqa: F405
        elif reader_type == JSON_EXTENSION_TYPE:
            return JsonReader().read(file_path)  # noqa: F405
        else:
            raise ReaderWriterFactoryError('There is no reader for file type: {}'.format(file_path))

    def create_writer(self, file_path, reversed_dict, extended_dict, output_dir):
        writer_type = self.__get_file_type(file_path)
        if writer_type == XML_EXTENSION_TYPE:
            return XmlWriter().write(reversed_dict, extended_dict, output_dir)
        elif writer_type == JSON_EXTENSION_TYPE:
            return JsonWriter().write(reversed_dict, None, output_dir)
        else:
            raise ReaderWriterFactoryError('There is no writer for file type: {}'.format(file_path))
